      "what": "围绕赛题设计并制作电子系统，融合模拟/数字电路、传感器、嵌入式控制、测量和调试。2025题目包含目标测量、定位、接收机、自动避障等。",
      "req": "2025通知采用自愿组队、每队3人，学校统一向赛区报名；本科/高职组别和2026安排以当届通知为准。",
