      "when": "2025届全国赛：2025-07-30 至 2025-08-02；该竞赛主赛通常隔年举行，2026专项/模拟赛通知不能等同于下一届全国赛。",
      "where": "赛区组织；2025各校按通知准备场地与仪器。",
      "status": "2025赛题与赛期已核实",
      "rationale": "物联网专业与传感器/嵌入式方向吻合，已有软件项目经验有助于控制逻辑与系统集成；当前C和硬件基础尚在建立，且3人团队需要补齐电路、仪器调试和焊接。学校相关专业教师与实验教学资源可能提供指导，但实际开放设备和竞赛队情况要向学院确认。",
